function dashboardForParent_(parent){var students=childViews_(parent.parent_id);return{children:students,notifications:notifications_(students.map(function(s){return s.student_id;})),upiId:getConfig_('upi_id'),academyName:getConfig_('academy_name')||'Eduwave Academy'};}
function childViews_(parentId){var ids=rows_(PORTAL.links).filter(function(r){return r.parent_id===parentId&&clean_(r.active).toLowerCase()==='true';}).map(function(r){return r.student_id;}),submissions=rows_(PORTAL.submissions);return rows_(PORTAL.students).filter(function(r){return ids.indexOf(r.student_id)!==-1&&clean_(r.enrollment_status).toLowerCase()==='active';}).map(function(s){var asns=rows_(PORTAL.assignments).filter(function(r){return r.student_id===s.student_id&&clean_(r.status).toLowerCase()==='published';}),resources=asns.map(function(a){var r=first_(PORTAL.resources,function(x){return x.resource_id===a.resource_id;}),sub=submissions.filter(function(x){return x.assignment_id===a.assignment_id&&x.student_id===s.student_id;})[0];return r?{assignment_id:a.assignment_id,resource_id:r.resource_id,title:a.title_override||r.title,subject:r.subject,kind:r.kind,submission_type:submissionType_(r),due_date:a.due_date,submission_status:sub?sub.status:submissionType_(r)==='view_only'?'view_only':'pending',submitted_at:sub?sub.submitted_at:''}:null;}).filter(Boolean),fees=rows_(PORTAL.fees).filter(function(r){return r.student_id===s.student_id;}).sort(newest_).slice(0,6),attendance=rows_(PORTAL.attendance).filter(function(r){return r.student_id===s.student_id;}).sort(newest_).slice(0,6),progress=rows_(PORTAL.progress).filter(function(r){return r.student_id===s.student_id;}).sort(newest_).slice(0,6);return{student_id:s.student_id,name:s.name,class_level:s.class_level,resources:resources,fees:fees,attendance:attendance,progress:progress};});}
function notifications_(ids){var today=date_(),notes=[],submissions=rows_(PORTAL.submissions);rows_(PORTAL.assignments).filter(function(r){return ids.indexOf(r.student_id)!==-1&&clean_(r.status).toLowerCase()==='published'&&(!r.visible_from||r.visible_from<=today);}).forEach(function(r){var resource=first_(PORTAL.resources,function(x){return x.resource_id===r.resource_id;}),sub=first_(PORTAL.submissions,function(x){return x.assignment_id===r.assignment_id&&x.student_id===r.student_id;});if(!sub||clean_(sub.status).toLowerCase()==='needs_changes')notes.push({type:'assignment',title:sub?'Changes requested':'Pending assignment',message:(resource?resource.title:'A new resource')+(sub&&sub.feedback?' - '+sub.feedback:' is ready to complete.'),student_id:r.student_id});});rows_(PORTAL.fees).filter(function(r){return ids.indexOf(r.student_id)!==-1&&clean_(r.status).toLowerCase()!=='paid';}).forEach(function(r){notes.push({type:'payment',title:'Fee update',message:r.billing_month+' fee of Rs '+r.amount+' is '+r.status+'.',student_id:r.student_id,fee_id:r.fee_id});});rows_(PORTAL.announcements).filter(function(r){return(!r.active_from||r.active_from<=today)&&(!r.active_until||r.active_until>=today)&&(r.audience==='all'||ids.indexOf(r.student_id)!==-1);}).forEach(function(r){notes.push({type:r.type||'exam',title:r.title,message:r.message,student_id:r.student_id});});return notes.slice(0,20);}
function adminFamilyDirectory_(parents,students,links){var activeLinks=links.filter(function(r){return clean_(r.active).toLowerCase()==='true';}),linked={};activeLinks.forEach(function(link){linked[link.student_id]=true;});var families=parents.map(function(parent){var children=links.filter(function(link){return link.parent_id===parent.parent_id;}).map(function(link){var student=students.filter(function(s){return s.student_id===link.student_id;})[0];if(!student)return null;return{student_id:student.student_id,name:student.name,class_level:student.class_level,enrollment_status:student.enrollment_status,monthly_fee:student.monthly_fee,due_day:student.due_day,relationship:link.relationship||'Parent',link_active:clean_(link.active).toLowerCase()==='true'};}).filter(Boolean).sort(function(a,b){var activeA=clean_(a.enrollment_status).toLowerCase()==='active'&&a.link_active,activeB=clean_(b.enrollment_status).toLowerCase()==='active'&&b.link_active;if(activeA!==activeB)return activeA?-1:1;return clean_(a.name).localeCompare(clean_(b.name));});return{parent_id:parent.parent_id,name:parent.name,email:parent.email,phone:parent.phone,status:parent.status,email_verified:!!parent.email_verified_at,children:children};}).sort(function(a,b){var activeA=clean_(a.status).toLowerCase()==='active',activeB=clean_(b.status).toLowerCase()==='active';if(activeA!==activeB)return activeA?-1:1;return clean_(a.name).localeCompare(clean_(b.name));});var unlinkedStudents=students.filter(function(student){return clean_(student.enrollment_status).toLowerCase()==='active'&&!linked[student.student_id];}).map(function(student){return{student_id:student.student_id,name:student.name,class_level:student.class_level,enrollment_status:student.enrollment_status,monthly_fee:student.monthly_fee,due_day:student.due_day};});return{families:families,unlinkedStudents:unlinkedStudents};}
